function initAudio() {
    if (!audioCtx) {
        audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    }
    if (audioCtx && audioCtx.state === 'suspended') {
        audioCtx.resume();
    }
    return audioCtx;
}

function toggleSound() {
    soundMuted = !soundMuted;
    const btn = document.getElementById('btnSoundToggle');
    if (btn) {
        btn.textContent = soundMuted ? '🔇 Sound: OFF' : '🔊 Sound: ON';
        btn.style.color = soundMuted ? '#ef4444' : '#10b981';
    }
}

function playSound(type) {
    if (soundMuted) return;
    try {
        const ctx = initAudio();
        if (!ctx) return;
        const now = ctx.currentTime;
        
        switch(type) {
            case 'buy': {
                const o1 = ctx.createOscillator();
                const g1 = ctx.createGain();
                o1.connect(g1); g1.connect(ctx.destination);
                o1.type = 'sine';
                o1.frequency.setValueAtTime(880, now);
                o1.frequency.setValueAtTime(1320, now + 0.08);
                g1.gain.setValueAtTime(0.18, now);
                g1.gain.exponentialRampToValueAtTime(0.001, now + 0.25);
                o1.start(now); o1.stop(now + 0.25);
                break;
            }
            case 'stock': {
                const o = ctx.createOscillator();
                const g = ctx.createGain();
                o.connect(g); g.connect(ctx.destination);
                o.type = 'triangle';
                o.frequency.setValueAtTime(220, now);
                o.frequency.exponentialRampToValueAtTime(60, now + 0.12);
                g.gain.setValueAtTime(0.2, now);
                g.gain.exponentialRampToValueAtTime(0.01, now + 0.14);
                o.start(now); o.stop(now + 0.14);
                break;
            }
            case 'feed': {
                const o = ctx.createOscillator();
                const g = ctx.createGain();
                o.connect(g); g.connect(ctx.destination);
                o.type = 'triangle';
                o.frequency.setValueAtTime(300, now);
                o.frequency.linearRampToValueAtTime(450, now + 0.06);
                o.frequency.linearRampToValueAtTime(320, now + 0.12);
                g.gain.setValueAtTime(0.15, now);
                g.gain.exponentialRampToValueAtTime(0.01, now + 0.15);
                o.start(now); o.stop(now + 0.15);
                break;
            }
            case 'autofeed': {
                [440, 554.37, 659.25, 880].forEach((freq, i) => {
                    const o = ctx.createOscillator();
                    const g = ctx.createGain();
                    o.connect(g); g.connect(ctx.destination);
                    o.type = 'sine';
                    o.frequency.setValueAtTime(freq, now + i * 0.05);
                    g.gain.setValueAtTime(0.12, now + i * 0.05);
                    g.gain.exponentialRampToValueAtTime(0.001, now + i * 0.05 + 0.18);
                    o.start(now + i * 0.05); o.stop(now + i * 0.05 + 0.18);
                });
                break;
            }
            case 'nextday': {
                [261.63, 329.63, 392.00, 523.25].forEach((f, idx) => {
                    const o = ctx.createOscillator();
                    const g = ctx.createGain();
                    o.connect(g); g.connect(ctx.destination);
                    o.type = 'sine';
                    o.frequency.setValueAtTime(f, now + idx * 0.04);
                    g.gain.setValueAtTime(0.12, now + idx * 0.04);
                    g.gain.exponentialRampToValueAtTime(0.001, now + idx * 0.04 + 0.4);
                    o.start(now + idx * 0.04); o.stop(now + idx * 0.04 + 0.4);
                });
                break;
            }
            case 'unlock': {
                [523.25, 659.25, 783.99, 1046.50].forEach((f, idx) => {
                    const o = ctx.createOscillator();
                    const g = ctx.createGain();
                    o.connect(g); g.connect(ctx.destination);
                    o.type = 'triangle';
                    o.frequency.setValueAtTime(f, now + idx * 0.08);
                    g.gain.setValueAtTime(0.18, now + idx * 0.08);
                    g.gain.exponentialRampToValueAtTime(0.001, now + idx * 0.08 + 0.35);
                    o.start(now + idx * 0.08); o.stop(now + idx * 0.08 + 0.35);
                });
                break;
            }
            case 'death': {
                const o = ctx.createOscillator();
                const g = ctx.createGain();
                o.connect(g); g.connect(ctx.destination);
                o.type = 'sawtooth';
                o.frequency.setValueAtTime(160, now);
                o.frequency.exponentialRampToValueAtTime(45, now + 0.6);
                g.gain.setValueAtTime(0.25, now);
                g.gain.exponentialRampToValueAtTime(0.01, now + 0.7);
                o.start(now); o.stop(now + 0.7);
                break;
            }
        }
    } catch(e) {}
}

// The same deterministic meal simulation powers daily processing and the planner.
// It returns new data so previews never consume food or mutate a save.
function simulateFridgeDay(country, foodStats, invincible = false) {
    const next = {
        ...country,
        fridge: { ...country.fridge },
        family: [...country.family],
        hunger: [...country.hunger],
        nutrition: country.nutrition.map(row => row.map(n => Math.max(0, n - 15)))
    };
    const foods = Object.entries(next.fridge).filter(([, food]) => food).map(([slot, food]) => ({ slot, food }));
    let deaths = 0, preferredFeeds = 0, fed = 0, unfed = 0;
    next.family.forEach((member, index) => {
        if (member === '💀') return;
        if (invincible) {
            next.hunger[index] = 100;
            next.nutrition[index] = [100, 100, 100];
            return;
        }
        if (foods.length) {
            let selected = foods.findIndex(item => country.preferences.includes(item.food));
            if (selected >= 0) preferredFeeds++;
            else selected = 0;
            const meal = foods.splice(selected, 1)[0];
            delete next.fridge[meal.slot];
            const stats = foodStats[meal.food] || { hunger: 40, nutrition: [10, 10, 10] };
            next.hunger[index] = Math.min(100, next.hunger[index] + stats.hunger);
            next.nutrition[index] = next.nutrition[index].map((n, i) => Math.min(100, n + Math.max(0, stats.nutrition[i] || 0)));
            fed++;
        } else {
            const depleted = next.nutrition[index].filter(n => n <= 0).length;
            next.hunger[index] = Math.max(0, next.hunger[index] - 20 - depleted * 5);
            unfed++;
        }
        if (next.hunger[index] <= 0) {
            next.family[index] = '💀';
            deaths++;
        }
    });
    const alive = next.family.filter(member => member !== '💀').length;
    return {
        country: next, deaths, preferredFeeds, fed, unfed,
        income: alive ? Math.round(country.budget * (alive / country.familySize) * 0.4) : 0,
        critical: next.family.filter((member, i) => member !== '💀' && next.hunger[i] <= 40).length
    };
}



function startGame() {
    document.getElementById('day-summary').textContent = '';
    gameRunning = true;
    gamePaused = false;
    day = 1;
    money = 1000;
    deaths = 0;
    feedStreak = 0;
    maxCombo = 0;
    inventory = {};
    selectedFood = null;
    generateShopStocks();
    
    // Initialize countries
    countries = {};
    Object.entries(COUNTRIES).forEach(([key, data]) => {
        if (data.unlockDay <= 1) {
            countries[key] = {
                name: data.name,
                familySize: data.familySize,
                budget: data.budget,
                preferences: data.preferences,
                fridge: {},
                family: generateFamily(data.familySize),
                hunger: Array(data.familySize).fill(100),
                nutrition: Array(data.familySize).fill(null).map(() => [20, 20, 20])
            };
        }
    });
    
    document.getElementById('startScreen').classList.add('hidden');
    document.getElementById('gameOverScreen').classList.add('hidden');
    document.getElementById('victoryScreen').classList.add('hidden');

    render();
    persistSave();
}

function generateFamily(size) {
    const family = [];
    for (let i = 0; i < size; i++) {
        family.push(HUMAN_EMOJIS[Math.floor(Math.random() * HUMAN_EMOJIS.length)]);
    }
    return family;
}

function nextDay() {
    if (!gameRunning || gamePaused) return;
    
    playSound('nextday');
    
    // Visual feedback - button animation
    const nextDayBtn = document.getElementById('btnNextDay');
    if (nextDayBtn) {
        nextDayBtn.classList.add('animating');
        nextDayBtn.textContent = '🌅 Advancing...';
        setTimeout(() => {
            nextDayBtn.classList.remove('animating');
            nextDayBtn.textContent = '➡️ Next Day';
        }, 600);
    }
    
    // Create flash effect
    const flash = document.createElement('div');
    flash.className = 'day-flash';
    document.body.appendChild(flash);
    setTimeout(() => flash.remove(), 800);
    
    // Process hunger and nutrition
    let totalDeaths = 0;
    let preferredFeeds = 0;
    let income = 0;
    Object.entries(countries).forEach(([key, country]) => {
        const outcome = simulateFridgeDay(country, FOOD_STATS, !!window.gameDebug?.godMode);
        countries[key] = outcome.country;
        totalDeaths += outcome.deaths;
        preferredFeeds += outcome.preferredFeeds;
        income += outcome.income;
    });
    deaths += totalDeaths;
    if (totalDeaths > 0) {
        playSound('death');
    }
    day++;
    
    // Animate day counter
    const dayCounter = document.getElementById('hudDay');
    if (dayCounter) {
        dayCounter.classList.add('day-updated');
        setTimeout(() => dayCounter.classList.remove('day-updated'), 500);
    }
    
    generateShopStocks();
    
    // Unlock new countries
    Object.entries(COUNTRIES).forEach(([key, data]) => {
        if (data.unlockDay <= day && !countries[key]) {
            countries[key] = {
                name: data.name,
                familySize: data.familySize,
                budget: data.budget,
                preferences: data.preferences,
                fridge: {},
                family: generateFamily(data.familySize),
                hunger: Array(data.familySize).fill(100),
                nutrition: Array(data.familySize).fill(null).map(() => [20, 20, 20])
            };
            playSound('unlock');
            showToast(`🌍 ${data.name} unlocked! Budget +$${data.budget}`, '#f59e0b');
        }
    });
    
    // DS-FRIDGE-01 fun: combo/streak toast when families get their favorite foods.
    if (preferredFeeds >= 2) {
        feedStreak++;
        maxCombo = Math.max(maxCombo, preferredFeeds);
        const bonus = preferredFeeds * 2;
        income += bonus;
        playSound('autofeed');
        showToast(`🔥 Tasty combo x${preferredFeeds}! Day streak ${feedStreak} (+$${bonus})`, '#f59e0b');
    } else if (preferredFeeds > 0) {
        feedStreak++;
        maxCombo = Math.max(maxCombo, preferredFeeds);
    } else {
        feedStreak = 0;
    }

    money += income;
    const summary = `Day ${day - 1} · Income $${income} · Favorite meals ${preferredFeeds} · Deaths ${totalDeaths}`;
    document.getElementById('day-summary').textContent = summary;

    // Check game over
    const aliveCount = Object.values(countries).reduce((sum, c) => sum + c.family.filter(m => m !== '💀').length, 0);
    
    if (aliveCount === 0) {
        gameRunning = false;
        playSound('death');
        showToast('💀 All families have perished!', '#ef4444');
        document.getElementById('finalDays').textContent = day;
        document.getElementById('finalDeaths').textContent = deaths;
        document.getElementById('finalMoney').textContent = '$' + money;
        document.getElementById('loss-day-summary').textContent = summary;
        document.getElementById('gameOverScreen').classList.remove('hidden');
    } else if (day >= 30) {
        gameRunning = false;
        playSound('victory');
        showToast('🏆 Global Food Hero Victory Achieved!', '#39ff14');
        document.getElementById('victoryDays').textContent = day;
        document.getElementById('victoryPopulation').textContent = aliveCount;
        document.getElementById('victoryMoney').textContent = '$' + money;
        document.getElementById('victory-day-summary').textContent = summary;
        document.getElementById('victoryScreen').classList.remove('hidden');
    }

    if (gameRunning) persistSave(); else clearSave();

    render();
}

function togglePause() {
    if (!gameRunning) return;
    gamePaused = !gamePaused;
    const pauseBtn = document.getElementById('btnPause');
    if (pauseBtn) {
        pauseBtn.textContent = gamePaused ? '▶️ Resume' : '⏸️ Pause';
    }
}

function resumeGame() {
    gamePaused = false;
    const pauseBtn = document.getElementById('btnPause');
    if (pauseBtn) {
        pauseBtn.textContent = '⏸️ Pause';
    }
}




// Day-survived score: days bank 100/day, mouths fed bank 10 each,
// deaths cost 25 each, streaks/combos add flavor points.
function getScore() {
    const alive = Object.values(countries).reduce((sum, c) => sum + c.family.filter(m => m !== '💀').length, 0);
    return Math.max(0, (day - 1) * 100 + alive * 10 - deaths * 25 + feedStreak * 15 + maxCombo * 10);
}

function generateShopStocks() {
    shopStocks = {};
    Object.entries(SHOPS).forEach(([key, shop]) => {
        const items = {};
        if (shop.stock === 'all') {
            Object.entries(FOOD_PRICES).forEach(([emoji, price]) => {
                items[emoji] = Math.ceil(price * shop.multiplier);
            });
        } else {
            const allFoods = Object.keys(FOOD_STATS);
            // Select 12 unique random foods for the shop stock
            const shuffled = [...allFoods].sort(() => 0.5 - Math.random());
            const selected = shuffled.slice(0, 12);
            selected.forEach(emoji => {
                const basePrice = FOOD_PRICES[emoji] || 2;
                items[emoji] = Math.ceil(basePrice * (shop.multiplier || 0.5));
            });
        }
        shopStocks[key] = items;
    });
}

function getShopItems() {
    return shopStocks[currentShop] || {};
}

function buyFood(emoji) {
    const shop = SHOPS[currentShop];
    const price = FOOD_PRICES[emoji] || 2;
    const finalPrice = Math.ceil(price * (shop.multiplier || 0.5));
    
    if (money >= finalPrice) {
        money -= finalPrice;
        inventory[emoji] = (inventory[emoji] || 0) + 1;
        playSound('buy');
        const fStats = FOOD_STATS[emoji];
        showToast(`🛒 Bought ${emoji} ${fStats ? fStats.name : ''} (-$${finalPrice})`, '#39ff14');
        render();
        persistSave();
    } else {
        playSound('death');
        showToast(`❌ Not enough funds for ${emoji} ($${finalPrice})!`, '#ef4444');
    }
}

function addToFridge(countryKey, slot) {
    const country = countries[countryKey];
    if (!country || country.fridge[slot]) return;
    // Tap-to-move: a picked-up fridge item takes priority over inventory selection
    if (selectedSlot) {
        const from = countries[selectedSlot.countryKey];
        const moving = from ? from.fridge[selectedSlot.slot] : null;
        if (moving) {
            delete from.fridge[selectedSlot.slot];
            country.fridge[slot] = moving;
            playSound('stock');
            showToast(`📦 Moved ${moving} to ${country.name.split(' ')[0]} shelf`, '#06b6d4');
        }
        selectedSlot = null;
        render();
        persistSave();
        return;
    }
    if (!selectedFood) {
        showToast('👆 Pick food from 🎒 Inventory first, then tap an empty (+) slot', '#06b6d4');
        // Nudge mobile users to the ledger/inventory view
        setMobileView('inventory');
        return;
    }
    country.fridge[slot] = selectedFood;
    inventory[selectedFood]--;
    if (inventory[selectedFood] <= 0) {
        delete inventory[selectedFood];
        selectedFood = null;
    }
    playSound('stock');
    render();
    persistSave();
}

function removeFromFridge(countryKey, slot) {
    const country = countries[countryKey];
    if (!country) return;
    const food = country.fridge[slot];
    if (!food) return;
    // Tap a filled slot with no inventory selection = pick up for tap-to-move.
    // Tap it again = put back to inventory. Tap another empty slot = move there.
    if (!selectedFood && (!selectedSlot || selectedSlot.countryKey !== countryKey || selectedSlot.slot !== slot)) {
        selectedSlot = { countryKey, slot };
        playSound('feed');
        showToast(`✋ Picked up ${food} — tap an empty slot to move it, or tap it again to unpack`, '#06b6d4');
        render();
        return;
    }
    if (selectedSlot && selectedSlot.countryKey === countryKey && selectedSlot.slot === slot && !selectedFood) {
        // Second tap on same filled slot unpacks to inventory
        selectedSlot = null;
    } else {
        selectedSlot = null;
    }
    delete country.fridge[slot];
    inventory[food] = (inventory[food] || 0) + 1;
    playSound('stock');
    render();
    persistSave();
}

function autoStockFridges() {
    if (!gameRunning || gamePaused) return;
    let stockedCount = 0;
    const invKeys = Object.keys(inventory).filter(k => inventory[k] > 0);
    if (invKeys.length === 0) {
        showToast('🎒 Inventory empty! Buy food from shops first.', '#f59e0b');
        return;
    }

    Object.entries(countries).forEach(([key, country]) => {
        for (let slot = 0; slot < 12; slot++) {
            if (!country.fridge[slot]) {
                // Prioritize preference
                let chosenFood = invKeys.find(f => inventory[f] > 0 && country.preferences.includes(f));
                if (!chosenFood) {
                    chosenFood = invKeys.find(f => inventory[f] > 0);
                }
                if (chosenFood) {
                    country.fridge[slot] = chosenFood;
                    inventory[chosenFood]--;
                    if (inventory[chosenFood] <= 0) {
                        delete inventory[chosenFood];
                    }
                    stockedCount++;
                }
            }
        }
    });

    if (stockedCount > 0) {
        playSound('autofeed');
        showToast(`⚡ Auto-stocked ${stockedCount} items into fridges!`, '#10b981');
        render();
        persistSave();
    } else {
        showToast('Fridges are already full!', '#f59e0b');
    }
}



// ===== DS-FRIDGE-01: SAVE SYSTEM (local autosave + v2 panel hooks, zero network) =====
function collectSaveData() {
    return {
        day,
        money,
        deaths,
        inventory: Object.assign({}, inventory),
        countries: JSON.parse(JSON.stringify(countries))
    };
}

function persistSave() {
    try {
        localStorage.setItem(FRIDGE_SAVE_KEY, JSON.stringify(collectSaveData()));
    } catch (e) { /* storage unavailable (private mode/sandbox) — session continues */ }
}

function clearSave() {
    try {
        localStorage.removeItem(FRIDGE_SAVE_KEY);
    } catch (e) { /* ignore */ }
}

function restoreSaveData(data) {
    if (!data || typeof data !== 'object') return false;
    if (!Number.isFinite(data.day) || !Number.isFinite(data.money) || !Number.isFinite(data.deaths)) return false;
    if (!data.inventory || typeof data.inventory !== 'object') return false;
    if (!data.countries || typeof data.countries !== 'object') return false;
    const nextInventory = {};
    Object.entries(data.inventory).forEach(([emoji, count]) => {
        if (FOOD_STATS[emoji] && Number.isFinite(count) && count > 0) {
            nextInventory[emoji] = Math.floor(count);
        }
    });
    const nextCountries = {};
    Object.entries(data.countries).forEach(([key, c]) => {
        if (!c || typeof c !== 'object' || !Array.isArray(c.family) || c.family.length === 0) return;
        nextCountries[key] = {
            name: typeof c.name === 'string' ? c.name : key,
            familySize: c.family.length,
            budget: Number.isFinite(c.budget) ? c.budget : 0,
            preferences: Array.isArray(c.preferences) ? c.preferences.filter(f => FOOD_STATS[f]) : [],
            fridge: (c.fridge && typeof c.fridge === 'object') ? c.fridge : {},
            family: c.family,
            hunger: Array.isArray(c.hunger) ? c.hunger : c.family.map(() => 100),
            nutrition: Array.isArray(c.nutrition) ? c.nutrition : c.family.map(() => [20, 20, 20])
        };
    });
    if (Object.keys(nextCountries).length === 0) return false;
    day = Math.max(1, Math.floor(data.day));
    money = data.money;
    deaths = Math.max(0, Math.floor(data.deaths));
    inventory = nextInventory;
    countries = nextCountries;
    return true;
}



function showToast(message, color = '#00f2fe') {
    const container = document.getElementById('toastContainer');
    if (!container) return;
    const toast = document.createElement('div');
    toast.className = 'game-toast';
    toast.style.borderColor = color;
    toast.style.boxShadow = `0 0 15px ${color}40`;
    // Text-only: toast strings are plain text + emoji; innerHTML here would
    // execute any markup a future caller interpolates.
    toast.textContent = message;
    container.appendChild(toast);
    setTimeout(() => {
        toast.classList.add('fade-out');
        setTimeout(() => toast.remove(), 400);
    }, 2400);
}

// ===== Mobile playable: Tap-to-stock shelves + swipeable family ledger =====
function isMobileLayout() {
    return true;
}

function setMobileView(view) {
    mobileView = view;
    document.querySelectorAll('.game-content .panel').forEach(p => {
        p.classList.toggle('active-view', p.dataset.mobileView === view);
    });
    document.querySelectorAll('#mobileTabbar .mtab').forEach(b => {
        b.classList.toggle('active', b.dataset.view === view);
    });
    if (view === 'fridges') requestAnimationFrame(scrollToShelf);
}

function updateShelfChrome() {
    const keys = Object.keys(countries);
    const dots = document.getElementById('shelfDots');
    const counter = document.getElementById('shelfCounter');
    if (counter) counter.textContent = `${keys.length ? Math.min(shelfIndex + 1, keys.length) : 0} / ${keys.length}`;
    if (!dots) return;
    dots.innerHTML = '';
    keys.forEach((_, i) => {
        const d = document.createElement('span');
        d.className = 'dot' + (i === shelfIndex ? ' on' : '');
        d.addEventListener('click', () => { shelfIndex = i; scrollToShelf(); updateShelfChrome(); });
        dots.appendChild(d);
    });
}

function scrollToShelf() {
    if (document.body.classList.contains('bounded-fridge')) return;
    const wrap = document.getElementById('countriesContainer');
    if (!wrap || !isMobileLayout()) return;
    const card = wrap.querySelector('.country-fridge');
    if (!card) return;
    const w = card.offsetWidth + 12;
    wrap.scrollTo({ left: shelfIndex * w, behavior: 'smooth' });
}

function initMobileControls() {
    // Tab bar
    document.querySelectorAll('#mobileTabbar .mtab').forEach(btn => {
        btn.addEventListener('click', () => setMobileView(btn.dataset.view));
    });
    // Desktop: show all panels; mobile: show active view only
    const applyLayout = () => {
        if (isMobileLayout()) {
            setMobileView(mobileView);
        } else {
            document.querySelectorAll('.game-content .panel').forEach(p => p.classList.add('active-view'));
        }
    };
    window.addEventListener('resize', applyLayout, { passive: true });
    applyLayout();

    // Swipe between shelves: track horizontal swipe on the carousel
    const wrap = document.getElementById('countriesContainer');
    if (wrap) {
        let startX = 0, startL = 0, swiping = false;
        wrap.addEventListener('touchstart', e => {
            if (e.touches.length !== 1) return;
            startX = e.touches[0].clientX; startL = wrap.scrollLeft; swiping = true;
        }, { passive: true });
        wrap.addEventListener('touchend', () => {
            if (!swiping) return;
            swiping = false;
            const card = wrap.querySelector('.country-fridge');
            const w = card ? card.offsetWidth + 12 : wrap.clientWidth * 0.88;
            shelfIndex = Math.max(0, Math.min(Object.keys(countries).length - 1,
                Math.round(wrap.scrollLeft / w)));
            updateShelfChrome();
        }, { passive: true });
        wrap.addEventListener('scroll', () => {
            const card = wrap.querySelector('.country-fridge');
            if (!card) return;
            const w = card.offsetWidth + 12;
            const i = Math.round(wrap.scrollLeft / w);
            if (i !== shelfIndex && i >= 0 && i < Object.keys(countries).length) {
                shelfIndex = i;
                updateShelfChrome();
            }
        }, { passive: true });
    }

    // Bottom-sheet grabber: tap/drag collapses & expands the family ledger
    const grabber = document.getElementById('familyGrabber');
    const familyPanel = document.getElementById('panelFamily');
    if (grabber && familyPanel) {
        let y0 = 0, dragging = false;
        const toggle = () => familyPanel.classList.toggle('sheet-collapsed');
        grabber.addEventListener('click', toggle);
        grabber.addEventListener('touchstart', e => {
            dragging = true; y0 = e.touches[0].clientY;
        }, { passive: true });
        grabber.addEventListener('touchend', e => {
            if (!dragging) return;
            dragging = false;
            const dy = (e.changedTouches[0] || {}).clientY - y0;
            if (Math.abs(dy) < 8) return; // plain tap already toggled via click
            familyPanel.classList.toggle('sheet-collapsed', dy > 0);
        }, { passive: true });
    }

    // Keyboard focus activation for shelf slots (Enter/Space) — tap equivalent
    document.addEventListener('keydown', e => {
        if ((e.key === 'Enter' || e.key === ' ') && document.activeElement &&
            document.activeElement.classList && document.activeElement.classList.contains('fridge-slot')) {
            e.preventDefault();
            document.activeElement.click();
        }
    });
}



function render() {
    // Update HUD
    document.getElementById('hudMoney').textContent = '$' + money;
    document.getElementById('hudDay').textContent = day;
    const totalPop = Object.values(countries).reduce((sum, c) => sum + c.family.filter(member => member !== '💀').length, 0);
    document.getElementById('hudPopulation').textContent = totalPop;
    document.getElementById('hudDeaths').textContent = deaths;
    // DS-FRIDGE-01: day-survived score in the HUD (badge created live — index.html untouched).
    let scoreEl = document.getElementById('hudScore');
    if (!scoreEl) {
        const hud = document.querySelector('.hud');
        if (hud) {
            const stat = document.createElement('div');
            stat.className = 'hud-stat';
            stat.innerHTML = '<span class="hud-label">⭐ Score</span> <span class="hud-value" id="hudScore">0</span>';
            hud.appendChild(stat);
            scoreEl = stat.querySelector('#hudScore');
        }
    }
    if (scoreEl) scoreEl.textContent = getScore();
    
    // Render shop
    const shopItems = getShopItems();
    const shopItemsDiv = document.getElementById('shopItems');
    shopItemsDiv.innerHTML = '';
    Object.entries(shopItems).forEach(([emoji, price]) => {
        const fStats = FOOD_STATS[emoji] || { name: 'Food', hunger: 40, nutrition: [0, 0, 0, 0, 0] };
        
        let nutHtml = '';
        fStats.nutrition.forEach((val, idx) => {
            if (val > 0) {
                const label = CATEGORY_LABELS[idx];
                const color = CATEGORY_COLORS[idx];
                nutHtml += `<div style="font-size: 0.65rem; color: ${color}; font-weight: bold; margin-top: 1px;">${label} +${val}</div>`;
            }
        });

        const div = document.createElement('div');
        div.className = 'shop-item';
        div.onclick = () => buyFood(emoji);
        div.innerHTML = `
            <span class="shop-item-emoji">${emoji}</span>
            <div class="shop-item-name" style="font-weight: 700; margin-top: 2px;">${fStats.name}</div>
            <div class="shop-item-price" style="color: var(--neon-green); font-size: 0.75rem; font-weight: 600; margin-top: 2px;">$${price}</div>
            <div class="shop-item-hunger" style="color: #ff4a4a; font-size: 0.65rem; font-weight: bold; margin-top: 3px;">❤️ Hunger +${fStats.hunger}</div>
            <div class="shop-item-nutrition-list" style="margin-top: 2px;">
                ${nutHtml}
            </div>
        `;
        shopItemsDiv.appendChild(div);
    });
    
    // Render inventory
    const inventoryListDiv = document.getElementById('inventoryList');
    if (inventoryListDiv) {
        inventoryListDiv.innerHTML = '';
        Object.entries(inventory).forEach(([emoji, count]) => {
            if (count <= 0) return;
            const fStats = FOOD_STATS[emoji] || { name: 'Food', hunger: 40, nutrition: [0, 0, 0, 0, 0] };
            
            let nutHtml = '';
            fStats.nutrition.forEach((val, idx) => {
                if (val > 0) {
                    const label = CATEGORY_LABELS[idx];
                    const color = CATEGORY_COLORS[idx];
                    nutHtml += `<div style="font-size: 0.6rem; color: ${color}; font-weight: bold; margin-top: 1px;">${label} +${val}</div>`;
                }
            });

            const itemDiv = document.createElement('div');
            itemDiv.className = 'inventory-item' + (selectedFood === emoji ? ' selected' : '');
            itemDiv.onclick = () => {
                selectedFood = selectedFood === emoji ? null : emoji;
                if (selectedFood) selectedSlot = null; // tap-to-stock wins over tap-to-move
                render();
                if (selectedFood && window.innerWidth <= 900) {
                    showToast(`👆 ${emoji} selected — tap a (+) shelf slot to stock it`, '#06b6d4');
                }
            };
            itemDiv.title = `${fStats.name} (Hunger +${fStats.hunger})`;
            itemDiv.innerHTML = `
                <span class="inventory-item-emoji">${emoji}</span>
                <span class="inventory-item-count">${count}</span>
                <div class="inventory-item-name" style="font-size: 0.65rem; font-weight: 700; margin-top: 2px; text-overflow: ellipsis; overflow: hidden; white-space: nowrap;">${fStats.name}</div>
                <div class="inventory-item-nutrition" style="margin-top: 1px;">
                    ${nutHtml}
                </div>
            `;
            inventoryListDiv.appendChild(itemDiv);
        });
        if (Object.values(inventory).reduce((sum, c) => sum + c, 0) === 0) {
            inventoryListDiv.innerHTML = `<div style="grid-column: 1/-1; text-align: center; color: var(--text-muted); font-size: 0.75rem; padding: 10px;">Empty. Buy food from the shops!</div>`;
        }
    }
    
    // Render countries
    const countriesDiv = document.getElementById('countriesContainer');
    countriesDiv.innerHTML = '';
    Object.entries(countries).forEach(([key, country]) => {
        const div = document.createElement('div');
        div.className = 'country-fridge';
        
        let gridHtml = '';
        for (let i = 0; i < 12; i++) {
            const food = country.fridge[i];
            const isPicked = selectedSlot && selectedSlot.countryKey === key && selectedSlot.slot === i;
            const dropHint = selectedSlot && !food ? ' drop-target' : '';
            if (food) {
                gridHtml += `<div class="fridge-slot filled tappable${isPicked ? ' picked-up' : ''}" role="button" tabindex="0" aria-label="Shelf item ${food}${isPicked ? ' picked up' : ''}" onclick="removeFromFridge('${key}', ${i})">${food}</div>`;
            } else {
                gridHtml += `<div class="fridge-slot empty tappable${dropHint}" role="button" tabindex="0" aria-label="Empty shelf slot ${i + 1}. Tap to stock." onclick="addToFridge('${key}', ${i})">+</div>`;
            }
        }
        
        div.innerHTML = `
            <div class="country-header">${country.name} (Budget: $${country.budget})</div>
            <div class="fridge-grid">
                ${gridHtml}
            </div>
        `;
        countriesDiv.appendChild(div);
    });
    
    // Render families
    const familiesDiv = document.getElementById('familiesList');
    familiesDiv.innerHTML = '';
    Object.entries(countries).forEach(([key, country]) => {
        const div = document.createElement('div');
        div.className = 'family-card';
        const avgHunger = country.hunger.reduce((a, b) => a + b, 0) / country.hunger.length;
        const hungerColor = avgHunger > 70 ? '#10b981' : avgHunger > 40 ? '#f59e0b' : '#ef4444';
        
        const avgNut = [0, 0, 0];
        country.nutrition.forEach(nut => {
            for (let idx = 0; idx < 3; idx++) {
                avgNut[idx] += nut[idx];
            }
        });
        const avgNutPct = avgNut.map(n => Math.round(n / country.nutrition.length));
        
        const memberHtml = country.family.map((member, i) => {
            const isDead = member === '💀';
            const h = country.hunger[i];
            const hColor = h > 70 ? '#10b981' : h > 40 ? '#f59e0b' : '#ef4444';
            return `
                <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 4px;">
                    <span>${member}</span>
                    <span style="font-size: 0.7rem; color: ${isDead ? '#ef4444' : hColor}; font-weight: bold;">
                        ${isDead ? 'DEAD' : h + '%'}
                    </span>
                </div>
            `;
        }).join('');
        
        div.innerHTML = `
            <div style="font-weight: bold; margin-bottom: 8px; font-size: 0.85rem; color: var(--neon-cyan);">${country.name.split(' ')[0]} Family</div>
            <div class="family-members-details" style="margin-bottom: 8px;">
                ${memberHtml}
            </div>
            <div class="nutrition-bars">
                ${avgNutPct.map((val, idx) => {
                    const color = CATEGORY_COLORS[idx];
                    const label = CATEGORY_LABELS[idx];
                    return `
                        <div class="nutrition-bar" title="${label}: ${val}%">
                            <div class="nutrition-fill" style="width: ${val}%; background: ${color};"></div>
                        </div>
                    `;
                }).join('')}
            </div>
            <div style="font-size: 0.6rem; color: var(--text-muted); display: flex; justify-content: space-between; margin-top: 4px;">
                <span>Pro</span><span>Carb</span><span>Vit</span>
            </div>
        `;
        familiesDiv.appendChild(div);
    });
    if (typeof updateShelfChrome === 'function') updateShelfChrome();
    refreshFridgePages();
    refreshFridgePlanner();
}

// One decision at a time: buy, choose stock, place it, then review families.
const fridgePages = new Map();

function fridgePageWindow(total, requested, size) {
    const pages = Math.max(1, Math.ceil(total / size));
    const page = Math.max(0, Math.min(pages - 1, requested));
    return { page, pages, start: page * size, end: Math.min(total, (page + 1) * size) };
}

function refreshFridgePages() {
    if (!document.body.classList.contains('bounded-fridge')) return;
    for (const [id, config] of fridgePages) {
        const list = document.getElementById(id);
        const cards = Array.from(list.children);
        const size = id === 'shopItems' || id === 'inventoryList' ? (window.innerWidth < 550 ? 2 : 4) : 1;
        const range = fridgePageWindow(cards.length, config.page, size);
        config.page = range.page;
        cards.forEach((card, i) => {
            card.hidden = i < range.start || i >= range.end;
            if (card.matches('.shop-item,.inventory-item')) {
                card.tabIndex = 0;
                card.setAttribute('role', 'button');
                card.setAttribute('aria-label', card.textContent.replace(/\s+/g, ' ').trim());
            }
        });
        config.label.textContent = `${config.name} ${range.page + 1} / ${range.pages}`;
        config.previous.disabled = range.page === 0;
        config.next.disabled = range.page === range.pages - 1;
    }
}

function addFridgePager(id, name) {
    const list = document.getElementById(id);
    const bar = document.createElement('nav');
    bar.className = 'fridge-page-controls';
    bar.setAttribute('aria-label', `${name} pages`);
    const previous = document.createElement('button');
    const next = document.createElement('button');
    const label = document.createElement('span');
    previous.textContent = '← Previous';
    next.textContent = 'Next →';
    previous.type = next.type = 'button';
    label.setAttribute('aria-live', 'polite');
    bar.append(previous, label, next);
    list.before(bar);
    const config = { page: 0, name, label, previous, next };
    fridgePages.set(id, config);
    previous.addEventListener('click', () => { config.page--; refreshFridgePages(); });
    next.addEventListener('click', () => { config.page++; refreshFridgePages(); });
}

function initFridgeScreens() {
    document.body.classList.add('bounded-fridge');
    const family = document.getElementById('panelFamily');
    const inventory = document.createElement('section');
    inventory.className = 'panel';
    inventory.id = 'panelInventory';
    inventory.dataset.mobileView = 'inventory';
    inventory.append(family.querySelector('h2'), document.getElementById('inventoryList'));
    document.getElementById('gameContent').append(inventory);
    const tab = document.createElement('button');
    tab.className = 'mtab';
    tab.dataset.view = 'inventory';
    tab.textContent = '🎒 Stock';
    tab.addEventListener('click', () => setMobileView('inventory'));
    document.getElementById('mobileTabbar').insertBefore(tab, document.querySelector('[data-view="fridges"]'));
    document.querySelectorAll('#mobileTabbar button').forEach(button => button.type = 'button');
    document.querySelectorAll('#panelShop h2')[1]?.remove();
    for (const [id, name] of [['shopItems', 'Food'], ['inventoryList', 'Stock'], ['countriesContainer', 'Country'], ['familiesList', 'Family']]) {
        addFridgePager(id, name);
    }
    const hint = document.createElement('p');
    hint.className = 'fridge-flow-hint';
    hint.textContent = 'Shop → Stock: choose food → Fridges: tap an empty slot → Ledger: review → Next Day';
    document.getElementById('mobileTabbar').after(hint);
    document.getElementById('shopTabs').addEventListener('click', () => {
        fridgePages.get('shopItems').page = 0;
        refreshFridgePages();
    });
    document.getElementById('inventoryList').addEventListener('click', event => {
        if (event.target.closest('.inventory-item') && selectedFood) setMobileView('fridges');
    });
    document.addEventListener('keydown', event => {
        if (event.repeat || !['Enter', ' '].includes(event.key)) return;
        const card = event.target.closest?.('.shop-item,.inventory-item');
        if (card) { event.preventDefault(); card.click(); }
    });
    window.addEventListener('resize', refreshFridgePages);
    setMobileView('shop');
    initFridgePlanner();
    refreshFridgePages();
}

document.addEventListener('DOMContentLoaded', initFridgeScreens);

let fridgePlanCountry = 0;

function refreshFridgePlanner() {
    const target = document.getElementById('fridgePlanDetails');
    if (!target) return;
    const entries = Object.entries(countries);
    fridgePlanCountry = Math.max(0, Math.min(entries.length - 1, fridgePlanCountry));
    target.replaceChildren();
    if (!entries.length) { target.textContent = 'Start a game to plan your first day.'; return; }
    const outcomes = entries.map(([, country]) => simulateFridgeDay(country, FOOD_STATS, !!window.gameDebug?.godMode));
    const total = outcomes.reduce((sum, result) => ({
        fed: sum.fed + result.fed, unfed: sum.unfed + result.unfed,
        deaths: sum.deaths + result.deaths, income: sum.income + result.income
    }), { fed: 0, unfed: 0, deaths: 0, income: 0 });
    const summary = document.createElement('p');
    summary.className = 'fridge-plan-summary';
    summary.textContent = `Day ${day + 1} forecast: ${total.fed} ${total.fed === 1 ? 'meal' : 'meals'} · ${total.unfed} without food · ${total.deaths} deaths · $${total.income} family income`;
    summary.dataset.risk = total.deaths ? 'danger' : total.unfed ? 'warning' : 'ready';
    const country = entries[fridgePlanCountry][1];
    const outcome = outcomes[fridgePlanCountry];
    const title = document.createElement('h3');
    title.textContent = `${country.name} · ${fridgePlanCountry + 1} / ${entries.length}`;
    const details = document.createElement('p');
    details.textContent = `${outcome.fed} fed, ${outcome.unfed} unfed. ${outcome.critical} survivors at 40% hunger or less after this day. Favorites: ${country.preferences.join(' ')}`;
    const advice = document.createElement('p');
    advice.textContent = outcome.deaths ? 'Urgent: add food to this fridge before advancing.' : outcome.unfed ? 'Stock one food item per living family member to avoid hunger loss.' : 'Meals are covered. Vary protein, carbs, and vitamins to prevent depleted nutrition.';
    const nutrition = document.createElement('p');
    const remaining = outcome.country.nutrition.filter((_, i) => outcome.country.family[i] !== '💀');
    if (!remaining.length) advice.textContent = 'This family has no projected survivors. Review other countries before advancing.';
    nutrition.textContent = remaining.length ? 'Projected nutrition: ' + CATEGORY_LABELS.map((label, i) => `${label} ${Math.round(remaining.reduce((sum, row) => sum + row[i], 0) / remaining.length)}%`).join(' · ') : 'No surviving family members in this forecast.';
    target.append(summary, title, details, nutrition, advice);
    document.getElementById('fridgePlanPrevious').disabled = fridgePlanCountry === 0;
    document.getElementById('fridgePlanNext').disabled = fridgePlanCountry >= entries.length - 1;
}

function initFridgePlanner() {
    const panel = document.createElement('section');
    panel.className = 'panel';
    panel.dataset.mobileView = 'plan';
    panel.innerHTML = '<h2 class="panel-title">Tomorrow’s plan</h2><nav class="fridge-page-controls" aria-label="Country forecasts"><button type="button" id="fridgePlanPrevious">← Previous</button><span>Country forecast</span><button type="button" id="fridgePlanNext">Next →</button></nav><div id="fridgePlanDetails" class="fridge-plan-details" aria-live="polite"></div>';
    document.getElementById('gameContent').append(panel);
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'mtab';
    button.dataset.view = 'plan';
    button.textContent = '📋 Plan';
    button.addEventListener('click', () => { refreshFridgePlanner(); setMobileView('plan'); });
    document.getElementById('mobileTabbar').append(button);
    document.getElementById('fridgePlanPrevious').addEventListener('click', () => { fridgePlanCountry--; refreshFridgePlanner(); });
    document.getElementById('fridgePlanNext').addEventListener('click', () => { fridgePlanCountry++; refreshFridgePlanner(); });
    refreshFridgePlanner();
}

function initFridgeBriefing() {
    const overlay = document.getElementById('startScreen');
    const story = overlay.querySelector('.story');
    const controls = overlay.querySelector('.controls-hint');
    const slides = [...story.children, ...controls.children];
    const content = document.createElement('section');
    content.className = 'fridge-briefing-content';
    content.setAttribute('aria-label', 'Game briefing');
    content.append(...slides);
    story.replaceWith(content);
    controls.remove();
    const navigation = document.createElement('nav');
    navigation.className = 'fridge-page-controls';
    navigation.setAttribute('aria-label', 'Briefing pages');
    const previous = document.createElement('button');
    const next = document.createElement('button');
    const label = document.createElement('span');
    previous.type = next.type = 'button';
    previous.textContent = '← Previous';
    next.textContent = 'Next →';
    label.setAttribute('aria-live', 'polite');
    let page = 0;
    const show = () => {
        slides.forEach((slide, index) => { slide.hidden = index !== page; });
        previous.disabled = page === 0;
        next.disabled = page === slides.length - 1;
        label.textContent = `Briefing ${page + 1} / ${slides.length}`;
    };
    previous.addEventListener('click', () => { page--; show(); });
    next.addEventListener('click', () => { page++; show(); });
    navigation.append(previous, label, next);
    content.after(navigation);
    show();
}

document.addEventListener('DOMContentLoaded', initFridgeBriefing);

// Keep keyboard interaction inside setup/results while a modal covers the game.
function initFridgeDialogs() {
    const main = document.getElementById('gameMain');
    const overlays = ['startScreen', 'gameOverScreen', 'victoryScreen'].map(id => document.getElementById(id));
    let current = null;
    overlays.forEach(overlay => {
        overlay.setAttribute('role', 'dialog');
        overlay.setAttribute('aria-modal', 'true');
        overlay.setAttribute('aria-label', overlay.querySelector('.logo-big').textContent.trim());
    });
    const synchronize = () => {
        const active = overlays.find(overlay => !overlay.classList.contains('hidden'));
        main.inert = !!active;
        if (active && current !== active) active.querySelector('button:not(:disabled)')?.focus();
        if (!active && current) document.getElementById('btnNextDay')?.focus();
        current = active;
    };
    const observer = new MutationObserver(synchronize);
    overlays.forEach(overlay => observer.observe(overlay, { attributes: true, attributeFilter: ['class'] }));
    synchronize();
}

document.addEventListener('DOMContentLoaded', initFridgeDialogs);
